      ruchang = 9,
      sentence = "Whenever she wants, she could charge you with privately divining the fate of a royal. That would be plenty to have you killed.",
      voice = 2,
      next = {72}
    },
    [72] = {
      beijing = 4672,
      dialog = 3,
      music = "1001_2022_If_I_Never_Met_You",
      renwu = "npc",
      sentence = "He seemed a little out of control, not composed like he usually was. His tone was hurried, with a hint of panic.",
      next = {73}
    },
    [73] = {
      beijing = 4672,
      dhead = 105,
      dialog = 1,
      music = "1001_2022_If_I_Never_Met_You",
      renming = "$u",
      renwu = "npc",
      sentence = "But I can't just stand by and watch you die!",
      next = {74}
    },
    [74] = {
      beijing = 4672,
      dhead = 106,
      dialog = 1,
      music = "1001_2022_If_I_Never_Met_You",
      renming = "$u",
      renwu = "npc",
      sentence = "I've said before, I want to take away all your troubles, and the kingdom's. Keeping your life worry-free is my duty.",
      next = {75}
    },
    [75] = {
      beijing = 4672,
      dialog = 3,
      idx = 3,
      music = "1001_2022_If_I_Never_Met_You",
      renwu = "npc",
      role1 = 3155000,
      role2 = 301101,
      role3 = 301211,
      roleanim = 1.2,
      ruchang = -1,
      sentence = "Kiro's pupils suddenly shrunk, and my wrist hurt under his grip.",
      next = {76}
    },
    [76] = {
      beijing = 4672,
      dialog = 3,
      music = "1001_2022_If_I_Never_Met_You",
      renwu = "npc",
      role1 = 3155000,
      role2 = 301101,
      role3 = 301211,
      roleanim = 1.2,
      sentence = "That gaze he was trying so mightily to control hovered over my body for a long while before he finally made up his mind to look me in the eyes.",
      next = {77}
    },
    [77] = {
      beijing = 4672,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "1001_2022_If_I_Never_Met_You",
      renming = "Kiro",
      renwu = "npc",
      role1 = 3155000,
      role2 = 301101,
      role3 = 301209,
      roleanim = 1.2,
      sentence = "Duty?",
      voice = 2,
      next = {78}
    },
    [78] = {
      beijing = 4672,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "1001_2022_If_I_Never_Met_You",
      renming = "Kiro",
      renwu = "npc",
      role1 = 3155000,
      role2 = 301101,
      role3 = 301209,
      roleanim = 1.2,
      sentence = "Very well. Then I'll answer you as the crown prince.",
      voice = 2,
      next = {79}
    },
    [79] = {
      beijing = 4672,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "1001_2022_If_I_Never_Met_You",
      renming = "Kiro",
      renwu = "npc",
      role1 = 3155000,
      role2 = 301101,
      role3 = 301209,
      roleanim = 1.2,
      sentence = "You need not concern yourself with these matters. You just need to tend to your own affairs.",
      voice = 2,
      next = {80}
    },
    [80] = {
      beijing = 4672,
      dhead = 106,
      dialog = 1,
      music = "1001_2022_If_I_Never_Met_You",
      renming = "$u",
      renwu = "npc",
      role1 = 3155000,
      role2 = 301101,
      role3 = 301211,
      roleanim = 1.2,
      sentence = "...",
      next = {81}
    },
    [81] = {
      beijing = 4672,
      dialog = 3,
      music = "1001_2022_If_I_Never_Met_You",
      renwu = "npc",
      role1 = 3155000,
      role2 = 301101,
      role3 = 301211,
      roleanim = 1.2,
      sentence = "The words that I hadn't been able to say instantly withered in my heart, turning into an expanse of stillness.",
      next = {82}
    },
    [82] = {
      beijing = 4672,
      dialog = 3,
      music = "1001_2022_If_I_Never_Met_You",
      renwu = "npc",
      role1 = 3155000,
      role2 = 301101,
      role3 = 301211,
      roleanim = 1,
      ruchang = 9,
      sentence = "Finally, I quietly opened his hand and calmly made a bow.",
      next = {83}
    },
    [83] = {
      beijing = 4672,
      dhead = 108,
      dialog = 1,
      music = "1001_2022_If_I_Never_Met_You",
      renming = "$u",
      renwu = "npc",
      sentence = "I am here to serve, Your Highness the Prince.",
      next = {84}
    },
    [84] = {
      beijing = 4672,
      dhead = 108,
      dialog = 1,
      music = "1001_2022_If_I_Never_Met_You",
      renming = "$u",
      renwu = "npc",
      sentence = "I have nothing further to report and shall be going now.",
      next = {85}
    },
    [85] = {
      beijing = 4672,
      dialog = 3,
      music = "1001_2022_If_I_Never_Met_You",
      renwu = "npc",
      sentence = "With that, I turned and left, picking up speed as I did.",
      next = {86}
    },
    [86] = {
      beijing = 4672,
      dialog = 3,
      music = "1001_2022_If_I_Never_Met_You",
      renwu = "npc",
      sentence = "As Kiro just said, I did have affairs I needed to tend to.",
      next = {87}
    },
    [87] = {
      beijing = 4672,
      dialog = 3,
      music = "1001_2022_If_I_Never_Met_You",
      renwu = "npc",
      sentence = "Since I am the stargazer, it's up to me to cast off this fate for you.",
      next = {0}
    }
  },
