  [441202] = {
    [1] = {
      beijing = 1152,
      dhead = 111,
      dialog = 1,
      music = "22_Despair",
      renming = "$u",
      renwu = "npc",
      sentence = "没找到？",
      next = {2}
    },
    [2] = {
      beijing = 1152,
      dialog = 3,
      music = "22_Despair",
      renwu = "npc",
      sentence = "白起没说话，似是默认。",
      next = {3}
    },
    [3] = {
      beijing = 1152,
      dhead = 105,
      dialog = 1,
      music = "22_Despair",
      renming = "$u",
      renwu = "npc",
      sentence = "……这也太奇怪了。一个大活人，又是警察，怎么会突然没消息呢？",
      next = {4}
    },
    [4] = {
      beijing = 1152,
      dialog = 3,
      music = "22_Despair",
      renwu = "npc",
      sentence = "嘟囔声消弭在迅速掠过的风中，我抿了抿唇，觉得事情有些诡异。",
      next = {5}
    },
    [5] = {
      beijing = 1152,
      dialog = 3,
      music = "22_Despair",
      renwu = "npc",
      sentence = "其实在这里能凑巧遇到白起也是因为一件怪事——署里有个同事这两天突然失联了。",
      next = {6}
    },
    [6] = {
      beijing = 1873,
      bganim = 0,
      dhead = 103,
      dialog = 1,
      mask = "memory",
      music = "22_Despair",
      renming = "$u",
      renwu = "npc",
      sentence = "小郑不见了？！",
      next = {7}
    },
    [7] = {
      beijing = 1873,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "晚餐的饭桌旁，听到消息的我险些让夹好的水饺飞了出去。",
      next = {8}
    },
    [8] = {
      beijing = 1873,
      dhead = 111,
      dialog = 1,
      mask = "memory",
      music = "22_Despair",
      renming = "$u",
      renwu = "npc",
      sentence = "他不是宣传部的吗？你们现在宣传部也要出任务吗？",
      next = {9}
    },
    [9] = {
      beijing = 1873,
      dialog = 2,
      idx = 4,
      male = 4,
      mask = "memory",
      music = "22_Despair",
      renming = "白起",
      renwu = "npc",
      role1 = 482000,
      role2 = 403110,
      role3 = 403203,
      role5 = 482401,
      ruchang = -1,
      sentence = "他做得不错，人也机灵，我就把他调岗了。",
      voice = 2,
      next = {10}
    },
    [10] = {
      beijing = 1873,
      dialog = 2,
      idx = 4,
      male = 4,
      mask = "memory",
      music = "22_Despair",
      renming = "白起",
      renwu = "npc",
      role1 = 482000,
      role2 = 403110,
      role3 = 403203,
      role5 = 482401,
      sentence = "他去那休假，说是玩一圈顺便还个愿，然后没过两天就失联了。",
      voice = 2,
      next = {11}
    },
    [11] = {
      beijing = 1873,
      dhead = 103,
      dialog = 1,
      mask = "memory",
      music = "22_Despair",
      renming = "$u",
      renwu = "npc",
      role1 = 482000,
      role2 = 403111,
      role3 = 403203,
      role5 = 482401,
      sentence = "……等、等一下，还愿？",
      next = {12}
    },
    [12] = {
      beijing = 1873,
      dialog = 2,
      idx = 4,
      male = 4,
      mask = "memory",
      music = "22_Despair",
      renming = "白起",
      renwu = "npc",
      role1 = 482000,
      role2 = 403111,
      role3 = 403203,
      role5 = 482401,
      sentence = "他之前在那执行阶段任务，跟了几个月的人也一直没有抓到。 ",
      voice = 2,
      next = {13}
    },
    [13] = {
      beijing = 1873,
      dialog = 2,
      idx = 4,
      male = 4,
      mask = "memory",
      music = "22_Despair",
      renming = "白起",
      renwu = "npc",
      role1 = 482000,
      role2 = 403111,
      role3 = 403203,
      role5 = 482401,
      sentence = "根据同行队员后来的描述，他本人的原话是……",
      voice = 2,
      next = {14}
    },
    [14] = {
      beijing = 1873,
      dialog = 2,
      idx = 4,
      male = 4,
      mask = "memory",
      music = "22_Despair",
      renming = "白起",
      renwu = "npc",
      role1 = 482000,
      role2 = 403111,
      role3 = 403203,
      role5 = 482401,
      sentence = "“感觉这脑子就莫名地咯噔了一下，看到了个神像，我实在是太饿了，就顺手对着祂祈祷了一下。”",
      voice = 2,
      next = {15}
    },
    [15] = {
      beijing = 1873,
      dialog = 2,
      idx = 4,
      male = 4,
      mask = "memory",
      music = "22_Despair",
      renming = "白起",
      renwu = "npc",
      role1 = 482000,
      role2 = 403111,
      role3 = 403203,
      role5 = 482401,
      sentence = "“希望能早点把人抓到，少加班。”",
      voice = 2,
      next = {16}
    },
    [16] = {
      beijing = 1873,
      dhead = 111,
      dialog = 1,
      mask = "memory",
      music = "22_Despair",
      renming = "$u",
      renwu = "npc",
      role1 = 482000,
      role2 = 403111,
      role3 = 403203,
      role5 = 482401,
      sentence = "……然后呢？",
      next = {17}
    },
    [17] = {
      beijing = 1873,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      role1 = 482000,
      role2 = 403102,
      role3 = 403203,
      role5 = 482401,
      sentence = "他似也是感到某种不理解与离谱，戳了戳碗里的饺子。",
      next = {18}
    },
    [18] = {
      beijing = 1873,
      dialog = 2,
      idx = 4,
      male = 4,
      mask = "memory",
      music = "22_Despair",
      renming = "白起",
      renwu = "npc",
      role1 = 482000,
      role2 = 403102,
      role3 = 403203,
      role5 = 482401,
      sentence = "然后他们跟着踪迹跑到了另一个城市，在落地的第二天就抓到了人。 ",
      voice = 2,
      next = {19}
    },
    [19] = {
      beijing = 1873,
      dialog = 2,
      idx = 4,
      male = 4,
      mask = "memory",
      music = "22_Despair",
      renming = "白起",
      renwu = "npc",
      role1 = 482000,
      role2 = 403111,
      role3 = 403203,
      role5 = 482401,
      sentence = "毕竟，我们已经充分掌握了嫌疑人的犯罪特征与行为习惯，他们之前没抓着人也只是大意才让人跑了。",
      voice = 2,
      next = {20}
    },
    [20] = {
      beijing = 1873,
      dialog = 2,
      idx = 4,
      male = 4,
      mask = "memory",
      music = "22_Despair",
      renming = "白起",
      renwu = "npc",
      role1 = 482000,
      role2 = 403111,
      role3 = 403203,
      role5 = 482401,
      sentence = "所以顺利抓到很正常。",
      voice = 2,
      next = {21}
    },
    [21] = {
      beijing = 1873,
      dhead = 111,
      dialog = 1,
      mask = "memory",
      music = "22_Despair",
      renming = "$u",
      renwu = "npc",
      role1 = 482000,
      role2 = 403111,
      role3 = 403203,
      role5 = 482401,
      sentence = "小郑……也是这么想的吗？",
      next = {22}
    },
    [22] = {
      beijing = 1873,
      dialog = 2,
      idx = 4,
      male = 4,
      mask = "memory",
      music = "22_Despair",
      renming = "白起",
      renwu = "npc",
      role1 = 482000,
      role2 = 403111,
      role3 = 403203,
      role5 = 482401,
      sentence = "他当然也认为是大家的功劳，但运气也是一部分吧。",
      voice = 2,
      next = {23}
    },
    [23] = {
      beijing = 1873,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      role1 = 482000,
      role2 = 403111,
      role3 = 403203,
      role5 = 482401,
      sentence = "白起挑了挑眉毛，脸上没什么情绪。",
      next = {24}
    },
    [24] = {
      beijing = 1873,
      dialog = 2,
      idx = 4,
      male = 4,
      mask = "memory",
      music = "22_Despair",
      renming = "白起",
      renwu = "npc",
      role1 = 482000,
      role2 = 403111,
